CREATE DATABASE isodemo;
\c isodemo

CREATE TABLE accounts (
    account_id  int PRIMARY KEY,
    owner_name  text NOT NULL,
    balance     numeric(12,2) NOT NULL
);

INSERT INTO accounts VALUES
    (1, 'Asha',  5000.00),
    (2, 'Ravi',  3000.00),
    (3, 'Meera', 7500.00);

CREATE TABLE doctors (
    doctor_name text PRIMARY KEY,
    on_call     boolean NOT NULL
);

INSERT INTO doctors VALUES
    ('Dr. Rao',   true),
    ('Dr. Iyer',  true),
    ('Dr. Khan',  false);

UPDATE accounts
   SET balance = CASE account_id WHEN 1 THEN 5000 WHEN 2 THEN 3000 ELSE 7500 END;
UPDATE doctors SET on_call = (doctor_name <> 'Dr. Khan');

BEGIN ISOLATION LEVEL REPEATABLE READ;
-- ... your statements ...
COMMIT;

BEGIN;
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SHOW transaction_isolation;
COMMIT;

-- Terminal 1
BEGIN;
SELECT balance FROM accounts WHERE account_id = 1;

-- Terminal 2
UPDATE accounts SET balance = balance - 1000 WHERE account_id = 1;

-- Terminal 1
SELECT balance FROM accounts WHERE account_id = 1;
COMMIT;

-- Terminal 1
BEGIN;
UPDATE accounts SET balance = 0 WHERE account_id = 1;

-- Terminal 2
BEGIN ISOLATION LEVEL READ UNCOMMITTED;
SELECT balance FROM accounts WHERE account_id = 1;
COMMIT;

-- Terminal 1
ROLLBACK;

-- Terminal 1
BEGIN;
SELECT balance FROM accounts WHERE account_id = 2;   -- app sees 3000

-- Terminal 2
BEGIN;
SELECT balance FROM accounts WHERE account_id = 2;   -- app sees 3000

-- Terminal 1 (3000 - 500)
UPDATE accounts SET balance = 2500.00 WHERE account_id = 2;

-- Terminal 2 (3000 - 800): this waits for Terminal 1
UPDATE accounts SET balance = 2200.00 WHERE account_id = 2;

-- Terminal 1
COMMIT;

-- Terminal 2 (its UPDATE has now finished)
COMMIT;
SELECT balance FROM accounts WHERE account_id = 2;

-- Terminal 1
BEGIN;
UPDATE accounts SET balance = balance - 500 WHERE account_id = 2;

-- Terminal 2 (waits for Terminal 1)
BEGIN;
UPDATE accounts SET balance = balance - 800 WHERE account_id = 2;

-- Terminal 1
COMMIT;

-- Terminal 2
COMMIT;
SELECT balance FROM accounts WHERE account_id = 2;

-- Terminal 1
BEGIN;
SELECT balance FROM accounts WHERE account_id = 2 FOR UPDATE;   -- 3000

-- Terminal 2 (blocks here until Terminal 1 ends)
BEGIN;
SELECT balance FROM accounts WHERE account_id = 2 FOR UPDATE;

-- Terminal 1
UPDATE accounts SET balance = 2500.00 WHERE account_id = 2;
COMMIT;

-- Terminal 2 now returns 2500, so the app writes 2500 - 800
UPDATE accounts SET balance = 1700.00 WHERE account_id = 2;
COMMIT;

-- Terminal 1
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT balance FROM accounts WHERE account_id = 1;

-- Terminal 2
UPDATE accounts SET balance = balance - 1000 WHERE account_id = 1;

-- Terminal 1
SELECT balance FROM accounts WHERE account_id = 1;
UPDATE accounts SET balance = balance + 200 WHERE account_id = 1;
SELECT balance FROM accounts WHERE account_id = 1;
ROLLBACK;
SELECT balance FROM accounts WHERE account_id = 1;

-- Terminal 1
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM doctors WHERE on_call;          -- 2, so Rao may leave

-- Terminal 2
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM doctors WHERE on_call;          -- 2, so Iyer may leave

-- Terminal 1
UPDATE doctors SET on_call = false WHERE doctor_name = 'Dr. Rao';

-- Terminal 2
UPDATE doctors SET on_call = false WHERE doctor_name = 'Dr. Iyer';

-- Terminal 1
COMMIT;

-- Terminal 2
COMMIT;
SELECT * FROM doctors ORDER BY doctor_name;

-- Terminal 1
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM doctors WHERE on_call;          -- 2

-- Terminal 2
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM doctors WHERE on_call;          -- 2

-- Terminal 1
UPDATE doctors SET on_call = false WHERE doctor_name = 'Dr. Rao';

-- Terminal 2
UPDATE doctors SET on_call = false WHERE doctor_name = 'Dr. Iyer';

-- Terminal 1
COMMIT;

-- Terminal 2
COMMIT;

-- Terminal 2: retry the whole transaction
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM doctors WHERE on_call;          -- now 1, so Iyer must stay
ROLLBACK;
SELECT * FROM doctors ORDER BY doctor_name;

-- Terminal 1
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM doctors WHERE on_call;

-- Terminal 2
SELECT pid, locktype, relation::regclass AS relation, page, mode
  FROM pg_locks
 WHERE mode = 'SIReadLock';

-- Terminal 1
ROLLBACK;

BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE, READ ONLY, DEFERRABLE;
SELECT sum(balance) AS total_balance FROM accounts;
SHOW transaction_read_only;
UPDATE accounts SET balance = 0 WHERE account_id = 1;
ROLLBACK;

CREATE ROLE report_user LOGIN;
ALTER ROLE report_user SET default_transaction_isolation = 'repeatable read';

SELECT r.rolname, s.setconfig
  FROM pg_db_role_setting s
  JOIN pg_roles r ON r.oid = s.setrole
 WHERE r.rolname = 'report_user';

